import{_ as t,o as a,c as r,a2 as d}from"./chunks/framework.Cu3jFwFD.js";const g=JSON.parse('{"title":"Upgrades (cards and relics)","description":"","frontmatter":{},"headers":[],"relativePath":"features/upgrades/design.md","filePath":"features/upgrades/design.md","lastUpdated":1794907169000}'),s={name:"features/upgrades/design.md"};function i(l,e,n,o,h,c){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="upgrades-cards-and-relics" tabindex="-1">Upgrades (cards and relics) <a class="header-anchor" href="#upgrades-cards-and-relics" aria-label="Permalink to &quot;Upgrades (cards and relics)&quot;">​</a></h1><p><strong>Status:</strong> <span class="status-badge status-designed">DESIGNED</span> · <strong>Updated:</strong> 2026-11-17 · <a href="./../../GDD">GDD</a></p><p>Between days the Garage is the player&#39;s hub: read the report, repair the van, take one free card, and optionally spend cash on rerolls and relics. Each run builds a different van. Cards come in Clean (solid, no downside) and Gamble (stronger, with a price). Serves <strong>Push your luck</strong>.</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ol><li>After each report of Day 1, 2 and 3 (when the run continues) the Garage offers 3 cards. The player must take exactly 1 for free: Start stays locked until a card is taken (<a class="decision-ref" href="/hex-gdd/GDD#d-065">D‑065</a>). A wrecked day still gives the card.</li><li>Each slot of an offer is a Gamble with a set chance, otherwise Clean; at least 1 card in every offer is Clean when the pool allows it.</li><li>The player may <strong>reroll</strong> all three cards before picking, for cash. The price rises with every reroll on the same offer.</li><li>Each card appears at most once per run. A card already owned is never offered again.</li><li>The Garage also has a <strong>relic shelf</strong>: 3 relics, bought with cash, each with a special effect. Relics are never offered as free cards.</li><li>All cards and relics are lost on game over (<a href="./../run-and-quota/design">run-and-quota</a>).</li><li>Repair is also paid here (<a href="./../damage-and-repair/design">damage-and-repair</a>).</li><li>Cargo is unlimited (<a class="decision-ref" href="/hex-gdd/GDD#d-028">D‑028</a>), so there are no capacity cards.</li><li><strong>Lightning shield</strong> (from Lightning Rod or Big Lightning Rod): the van holds one shield. A normal strike that would hit the van is absorbed instead (RESIST effect, no HP lost) and the shield empties; it refills by itself after the refill time (<a class="decision-ref" href="/hex-gdd/GDD#d-050">D‑050</a>). Big violet strikes ignore the shield unless the van has the Grounding Coil relic (<a class="decision-ref" href="/hex-gdd/GDD#d-053">D‑053</a>).</li><li>The HUD shows a shield icon with a refill ring while the van has a shield (<a class="decision-ref" href="/hex-gdd/GDD#d-051">D‑051</a>).</li><li>Owning both rod cards gives one shield with the faster 10 s refill. Big Lightning Rod alone also grants the shield.</li><li>While Zeus&#39;s ward is active (<a href="./../packages/design">packages</a>), strikes are turned away by the ward and the shield is not used.</li><li>Grounding Coil appears on the relic shelf only when the van already has a shield.</li></ol><h2 id="numbers" tabindex="-1">Numbers <a class="header-anchor" href="#numbers" aria-label="Permalink to &quot;Numbers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Value</th><th>Unit</th><th>What to watch in playtests</th></tr></thead><tbody><tr><td>Cards per offer</td><td>3</td><td>cards</td><td></td></tr><tr><td>Gamble chance per slot</td><td>35 <mark class="tune">TUNE</mark></td><td>%</td><td>Share of Gamble cards taken</td></tr><tr><td>Reroll price</td><td>30 + 30 per earlier reroll <mark class="tune">TUNE</mark></td><td>$</td><td>Rerolls per run</td></tr><tr><td>Relic slots</td><td>3</td><td>relics</td><td></td></tr><tr><td>Shield refill, Lightning Rod / Big Lightning Rod</td><td>20 / 10 <mark class="tune">TUNE</mark></td><td>s</td><td>Strikes absorbed per shift; the card should feel worth a pick</td></tr></tbody></table><p><strong>Cards (Clean / Gamble)</strong></p><table tabindex="0"><thead><tr><th>Card</th><th>Kind</th><th>Effect</th></tr></thead><tbody><tr><td>Engine</td><td>Clean</td><td>Speed +20%</td></tr><tr><td>Turbo</td><td>Gamble</td><td>Speed +35%, grip −20%</td></tr><tr><td>Lightning Rod</td><td>Clean</td><td>A lightning shield that absorbs one normal strike, then refills 20 s after use (<a class="decision-ref" href="/hex-gdd/GDD#d-050">D‑050</a>)</td></tr><tr><td>Big Lightning Rod</td><td>Gamble</td><td>The shield refills twice as fast (10 s), but the shift is 10 s shorter, so overtime and the storm come sooner (<a class="decision-ref" href="/hex-gdd/GDD#d-052">D‑052</a>, <a class="decision-ref" href="/hex-gdd/GDD#d-043">D‑043</a>)</td></tr><tr><td>Soft Bumper</td><td>Clean</td><td>Repair price −10%</td></tr><tr><td>Steel Bumper</td><td>Gamble</td><td>Repair price −40%, acceleration −10%</td></tr><tr><td>Nitro Tank</td><td>Clean</td><td>+1 nitro bar (<a href="./../driving/design">driving</a>)</td></tr><tr><td>Wide Dock</td><td>Clean</td><td>Pickup and drop zones +50% wider <mark class="tune">TUNE</mark> (Delivery theme, <a class="decision-ref" href="/hex-gdd/GDD#d-041">D‑041</a>)</td></tr><tr><td>Blessed Courier</td><td>Gamble</td><td>Zeus ward lasts +15 s, but Safe packages pay −10% <mark class="tune">TUNE</mark> (Delivery theme, <a class="decision-ref" href="/hex-gdd/GDD#d-041">D‑041</a>)</td></tr></tbody></table><p><strong>Relics (price)</strong></p><table tabindex="0"><thead><tr><th>Relic</th><th>Price</th><th>Effect</th></tr></thead><tbody><tr><td>Hephaestus Wrench</td><td>120</td><td>Repairs cost half</td></tr><tr><td>Grounding Coil</td><td>160</td><td>The lightning shield also absorbs big violet strikes (<a class="decision-ref" href="/hex-gdd/GDD#d-053">D‑053</a>)</td></tr><tr><td>Overtime Contract</td><td>180</td><td>Overtime deliveries pay +0.5× more</td></tr><tr><td>Hermes&#39; Sandals</td><td>220</td><td>The van is 8% faster</td></tr><tr><td>Golden Wings</td><td>260</td><td>Every delivery pays 15% more</td></tr></tbody></table><h2 id="edge-cases" tabindex="-1">Edge cases <a class="header-anchor" href="#edge-cases" aria-label="Permalink to &quot;Edge cases&quot;">​</a></h2><ul><li>Rerolling is only possible before the free pick.</li><li>If the pool is exhausted the offer shows fewer than 3 cards.</li><li>Cash is spent in one place across repair, rerolls and relics; spending never lowers profit.</li></ul><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ul><li><mark class="tune">TUNE</mark> Card and relic numbers, the Gamble chance and the reroll price are the prototype&#39;s.</li><li>Cargo theme replaced by a Delivery theme (<a class="decision-ref" href="/hex-gdd/GDD#d-041">D‑041</a>); its two cards are new and untested.</li><li>Cash buys relics only; the old &quot;extra card for cash&quot; is dropped (<a class="decision-ref" href="/hex-gdd/GDD#d-040">D‑040</a>).</li><li>The old pool target was about 16 cards; the prototype has 7 cards and 5 relics.</li></ul><h2 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h2><ul><li>2026-11-17: designed. Capacity cards (Roof Rack, Overload) removed by <a class="decision-ref" href="/hex-gdd/GDD#d-028">D‑028</a>. Relics added from the prototype. Combo and pay multipliers no longer interact with the cut combo (<a class="decision-ref" href="/hex-gdd/GDD#d-029">D‑029</a>).</li></ul>',17)])])}const p=t(s,[["render",i]]);export{g as __pageData,p as default};
